const AUTO={en:AUTO_EN,de:AUTO_DE,ar:AUTO_AR};
const trL=v=>{v=String(v==null?'':v);const L=lg();return L==='tr'?v:(((AUTO[L]||{})[v])||v);};
const hasVal=e=>Array.isArray(e)?e.length>0:!!(e&&String(e).trim());
/* öğenin yerelleştirilmiş alanı: önce panelde girilen çeviri, sonra hazır çeviri, sonra Türkçe */
const LF=(it,f)=>{
  const L=lg();if(L==='tr')return it[f];
  const e=it[L]&&it[L][f];if(hasVal(e))return e;
  const v=it[f];return Array.isArray(v)?v.map(trL):trL(v);
};
const LT=k=>{
  const L=lg();if(L==='tr')return state.texts[k];
  const e=state[L]&&state[L].texts&&state[L].texts[k];if(hasVal(e))return e;
  const v=state.texts[k];return k==='gChecks'?String(v).split('\n').map(trL).join('\n'):trL(v);
};
const LS=(k,v)=>{ /* slogan, saat, adres */
  const L=lg();if(L==='tr')return v;
  const e=state[L]&&state[L][k];return hasVal(e)?e:trL(v);
};
/* kur: 1 USD ve 1 EUR kaç ₺. Canlı kur alınamazsa yedek değer kullanılır. */
const FX_FALLBACK={USD:50,EUR:58};
const FX={USD:0,EUR:0};
function fxRate(c){
  const f=state.fx||{};
  const m=parseFloat(String(c==='EUR'?f.manualEur:f.manual||'').replace(',','.'));
  if(m>0)return m;
  return FX[c]>0?FX[c]:FX_FALLBACK[c];
}
/* ₺ fiyatını seçili para birimine çevirir. Panelde o dil için fiyat yazıldıysa o kullanılır. */
function priceText(p){
  const L=lg();if(L==='tr')return p.price;
  const o=p[L]&&p[L].price;if(hasVal(o))return o;
  const raw=String(p.price||'');
  if(/[$€£]|\busd\b|\beur\b/i.test(raw))return raw;
  const m=raw.match(/\d[\d.,]*/);if(!m)return raw;
  const tl=parseFloat(m[0].replace(/\./g,'').replace(',','.'));
  if(!isFinite(tl)||tl<=0)return raw;
  const v=tl/fxRate(CURS[L]);
  const step=v<50?1:v<500?5:10;
  const n=Math.max(step,Math.round(v/step)*step);
  return L==='de'?n.toLocaleString('de-DE')+' €':'$'+n.toLocaleString('en-US');
}
function refreshPrices(){
  $$('[data-pid]').forEach(el=>{const p=state.packages.find(x=>x.id===el.dataset.pid);if(p)el.textContent=priceText(p);});
}
async function fxInit(){
  try{
    const c=JSON.parse(localStorage.getItem('iw-fx2')||'null');
    if(c&&c.USD>0&&c.EUR>0){FX.USD=c.USD;FX.EUR=c.EUR;if(Date.now()-c.t<12*3600e3){refreshPrices();return;}}
  }catch(e){}
  try{
    const r=await fetch('https://open.er-api.com/v6/latest/USD');
    const j=await r.json();const t=j&&j.rates&&+j.rates.TRY,e=j&&j.rates&&+j.rates.EUR;
    if(t>0&&e>0){FX.USD=t;FX.EUR=t/e;try{localStorage.setItem('iw-fx2',JSON.stringify({USD:FX.USD,EUR:FX.EUR,t:Date.now()}));}catch(x){}refreshPrices();}
  }catch(e){}
}
function setLang(l){
  LANG=LANGS.indexOf(l)>=0?l:'tr';
  try{localStorage.setItem('iw-lang',LANG);}catch(e){}
  renderSite();renderPill();
}

