/* ---------- telefon / bağlantı ---------- */
function phone10(p){let d=digits(p);if(d.startsWith('90')&&d.length>=12)d=d.slice(2);if(d.startsWith('0'))d=d.slice(1);return d;}
function phoneDisp(p){const d=phone10(p);return d.length===10?`0${d.slice(0,3)} ${d.slice(3,6)} ${d.slice(6,8)} ${d.slice(8)}`:String(p||'');}
function phoneTel(p){const d=phone10(p);return d.length===10?'+90'+d:(digits(p)?'+'+digits(p):'');}
function waNum(){const c=state.contact;const src=c.whatsapp||c.phone;const d=phone10(src);return d.length===10?'90'+d:digits(src);}
function waLink(text){return 'https://wa.me/'+waNum()+(text?'?text='+encodeURIComponent(text):'');}
function normUrl(u){u=String(u||'').trim();if(!u)return '';if(!/^https?:\/\//i.test(u))u='https://'+u;try{const x=new URL(u);return(/\./.test(x.hostname)||x.hostname==='localhost')?x.href:'';}catch(e){return '';}}
function hostOf(u){try{return new URL(u).hostname.replace(/^www\./,'');}catch(e){return String(u||'');}}
function shortUrl(u){try{const x=new URL(u);return x.hostname.replace(/^www\./,'')+(x.pathname!=='/'?x.pathname.replace(/\/$/,''):'');}catch(e){return String(u||'');}}
function igUrl(v){v=String(v||'').trim();if(!v)return '';if(/instagram\.com/i.test(v))return normUrl(v);return 'https://instagram.com/'+v.replace(/^@/,'').replace(/\s/g,'');}
function igHandle(v){v=String(v||'').trim();if(!v)return '';if(/instagram\.com/i.test(v)){try{return '@'+new URL(normUrl(v)).pathname.replace(/\//g,'');}catch(e){return v;}}return '@'+v.replace(/^@/,'');}

/* ---------- veri katmanı ---------- */
const Store={
  db:null,ok:false,
  open(){return new Promise(res=>{try{const r=indexedDB.open('irakliweb-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('kv');r.onsuccess=()=>res(r.result);r.onerror=()=>res(null);r.onblocked=()=>res(null);}catch(e){res(null);}});},
  async load(){try{this.db=await this.open();if(!this.db)return null;this.ok=true;return await new Promise(res=>{const q=this.db.transaction('kv').objectStore('kv').get('state');q.onsuccess=()=>res(q.result||null);q.onerror=()=>res(null);});}catch(e){return null;}},
  save(s){try{if(!this.db)return;this.db.transaction('kv','readwrite').objectStore('kv').put(s,'state');}catch(e){}}
};

/* ---------- şifre: düz metin tutulmaz; PBKDF2 özeti + AES-GCM (token şifreleme) ---------- */
const DEFAULT_AUTH={"salt": "1e99e19900864785c684670cdec4f9e8", "iter": 310000, "verify": "03601c82d8c64beb19cd9e7a62eb5d53dd1a55e6ca02c3737789f8e0d7a46382"};
const PW={
  ok(){return !!(window.crypto&&crypto.subtle);},
  hex(b){return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');},
  unhex(h){return new Uint8Array((h.match(/../g)||[]).map(x=>parseInt(x,16)));},
  async derive(pw,salt,iter){
    const km=await crypto.subtle.importKey('raw',new TextEncoder().encode(pw),'PBKDF2',false,['deriveBits']);
    const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:this.unhex(salt),iterations:iter},km,512);
    const verify=this.hex(bits.slice(0,32));
    const key=await crypto.subtle.importKey('raw',bits.slice(32),'AES-GCM',false,['encrypt','decrypt']);
    return {verify,key};
  },
  async make(pw){const salt=this.hex(crypto.getRandomValues(new Uint8Array(16))),iter=310000;const d=await this.derive(pw,salt,iter);return {salt,iter,verify:d.verify,key:d.key};},
  async enc(key,text){const iv=crypto.getRandomValues(new Uint8Array(12));const ct=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(text));return {iv:this.hex(iv),ct:this.hex(ct)};},
  async dec(key,o){try{const t=await crypto.subtle.decrypt({name:'AES-GCM',iv:this.unhex(o.iv)},key,this.unhex(o.ct));return new TextDecoder().decode(t);}catch(e){return null;}},
  same(a,b){if(a.length!==b.length)return false;let r=0;for(let i=0;i<a.length;i++)r|=a.charCodeAt(i)^b.charCodeAt(i);return r===0;}
};
/* yanlış deneme sınırı (bu cihazda): 5 yanlış = 5 dk bekleme */
const Throttle={
  get(){try{return JSON.parse(localStorage.getItem('ob-fail')||'{}');}catch(e){return {};}},
  wait(){const f=this.get();return f.until&&f.until>Date.now()?Math.ceil((f.until-Date.now())/1000):0;},
  fail(){const f=this.get();f.n=(f.n||0)+1;if(f.n>=5){f.until=Date.now()+300000;f.n=0;}try{localStorage.setItem('ob-fail',JSON.stringify(f));}catch(e){}},
  clear(){try{localStorage.removeItem('ob-fail');}catch(e){}}
};

/* ---------- sunucu katmanı (api.php): tüm cihazlar ve ziyaretçiler aynı veriyi görür ---------- */
const Server={
  on:false,why:'',mode:'',base:'/api',gh:{repo:'',branch:'main',sha:'',auth:null},rev:0,token:'',defaultPw:false,saving:false,pending:false,
  /* ===== GitHub modu: veri deponun data/ klasörüne yazılır, GitHub Pages herkese sunar ===== */
  b64(str){const by=new TextEncoder().encode(str);let bin='';for(let i=0;i<by.length;i+=0x8000)bin+=String.fromCharCode.apply(null,by.subarray(i,i+0x8000));return btoa(bin);},
  async ghApi(path,tok,opt){
    try{return await fetch('https://api.github.com'+path,Object.assign({cache:'no-store'},opt||{},{headers:Object.assign({Accept:'application/vnd.github+json','Authorization':'Bearer '+tok},(opt&&opt.headers)||{})}));}
    catch(e){return null;}
  },
  async ghStatic(name){
    const one=async url=>{try{const r=await fetch(url+'?_='+Date.now(),{cache:'no-store'});if(r.status!==200)return {status:r.status,j:null};let j=null;try{j=await r.json();}catch(e){return {status:200,j:null,bad:true};}return {status:200,j};}catch(e){return {status:0,j:null};}};
    let r=await one('data/'+name);
    if(name==='auth.json'&&!(r.status===200&&r.j))     /* dosya klasörsüz (kök dizine) yüklenmişse onu da dene */
      {const r2=await one(name);if(r2.status===200&&r2.j&&r2.j.v===1)return r2;}
    return r;
  },
  /* depodaki dosyanın güncel sha ve içeriği (yönetici); {sha,json} | null (yok) | undefined (hata) */
  async ghFile(name,tok,wantBody){
    const g=this.gh,q='?ref='+encodeURIComponent(g.branch||'main');
    const ls=await this.ghApi('/repos/'+g.repo+'/contents/data'+q,tok);
    if(!ls)return undefined;
    if(ls.status===404)return null;
    if(ls.status!==200)return undefined;
    const arr=await ls.json();const it=(arr||[]).find(x=>x.name===name);
    if(!it)return null;
    if(!wantBody)return {sha:it.sha};
    const r=await this.ghApi('/repos/'+g.repo+'/contents/data/'+name+q,tok,{headers:{Accept:'application/vnd.github.raw+json'}});
    if(!r||r.status!==200)return undefined;
    let j=null;try{j=JSON.parse(await r.text());}catch(e){}
    return {sha:it.sha,json:j};
  },
  async ghPut(name,obj,sha,tok,msg){
    const g=this.gh;
    const body={message:msg||'Panel güncellemesi',content:this.b64(JSON.stringify(obj)),branch:g.branch||'main'};
    if(sha)body.sha=sha;
    const r=await this.ghApi('/repos/'+g.repo+'/contents/data/'+name,tok,{method:'PUT',body:JSON.stringify(body),headers:{'Content-Type':'application/json'}});
    if(!r)return {status:0};
    let j=null;try{j=await r.json();}catch(e){}
    return {status:r.status,j};
  },
  async ghCall(a,body,tok){
    const R=(status,j)=>({status,j}),g=this.gh;
    tok=tok||this.token||this.getToken();
    if(a==='state'||a==='rev'){
      let rev=0,state=null;
      if(tok&&g.repo){
        const d=await this.ghFile('state.json',tok,true);
        if(d===undefined){const s=await this.ghStatic('state.json');if(s.status===0)return R(0,null);if(s.j&&s.j.state){rev=s.j.rev|0;state=s.j.state;}}
        else if(d){g.sha=d.sha;if(d.json&&d.json.state){rev=d.json.rev|0;state=d.json.state;}}
        else g.sha='';
      }else{
        const s=await this.ghStatic('state.json');
        if(s.status===0)return R(0,null);
        if(s.j&&s.j.state){rev=s.j.rev|0;state=s.j.state;}
      }
      return R(200,{ok:true,rev,state});
    }
    if(a==='check'){
      if(!tok||!g.repo)return R(401,{ok:false});
      const r=await this.ghApi('/repos/'+g.repo,tok);
      if(!r)return R(0,null);
      if(r.status===401||r.status===403||r.status===404)return R(401,{ok:false});
      let j=null;try{j=await r.json();}catch(e){}
      if(!(j&&j.permissions&&j.permissions.push))return R(401,{ok:false});
      const au=await this.ghStatic('auth.json');       /* şifre başka yerden değiştiyse bu cihazın oturumu biter */
      let mine=0;try{mine=parseInt(localStorage.getItem('ob-sv')||'0',10)||0;}catch(e){}
      if(au.j&&(au.j.sv|0)>mine)return R(401,{ok:false});
      return R(200,{ok:true,defaultPw:false});
    }
    if(a==='login'){
      if(!PW.ok())return R(0,{error:'secure'});
      const w=Throttle.wait();if(w)return R(429,{ok:false,wait:w});
      const au=await this.ghStatic('auth.json');
      if(au.status===0)return R(0,null);
      const A0=au.j;if(!(A0&&A0.v===1&&A0.salt&&A0.verify))return R(0,null);
      const d=await PW.derive(String(body.pw||''),A0.salt,A0.iter);
      if(!body.pw||!PW.same(d.verify,A0.verify)){Throttle.fail();return R(401,{ok:false});}
      Throttle.clear();
      g.auth=A0;if(A0.repo)g.repo=A0.repo;if(A0.branch)g.branch=A0.branch;
      try{localStorage.setItem('ob-sv',String(A0.sv|0));}catch(e){}
      if(!A0.tokenEnc)return R(200,{ok:true,needSetup:true,token:''});
      const t=await PW.dec(d.key,A0.tokenEnc);
      if(!t)return R(200,{ok:true,needSetup:true,token:''});
      /* yönetici olarak güncel veriyi ve dosya sürümünü al (başkasının değişikliğini ezmemek için) */
      const fr=await this.ghFile('state.json',t,true);
      if(fr===undefined){const rr=await this.ghApi('/repos/'+g.repo,t);if(rr&&rr.status===401)return R(200,{ok:true,needSetup:true,token:''});}  /* token süresi dolmuş: yeniden bağla */
      if(fr!==undefined){g.sha=(fr&&fr.sha)||'';g.fresh=(fr&&fr.json&&fr.json.state)?{rev:fr.json.rev|0,state:fr.json.state}:null;}
      return R(200,{ok:true,token:t,defaultPw:false});
    }
    if(a==='setup'){   /* tek seferlik: repo + token + şifre -> data/auth.json */
      const repo=String(body.repo||'').trim().replace(/^https?:\/\/github\.com\//,'').replace(/\/$/,''),branch=String(body.branch||'main').trim()||'main',t=String(body.token||'').trim();
      if(!/^[\w.-]+\/[\w.-]+$/.test(repo))return R(400,{ok:false,error:'repo'});
      const r=await this.ghApi('/repos/'+repo,t);
      if(!r)return R(0,null);
      if(r.status===401)return R(401,{ok:false,error:'token'});
      if(r.status===404)return R(404,{ok:false,error:'repo'});
      let j=null;try{j=await r.json();}catch(e){}
      if(!(j&&j.permissions&&j.permissions.push))return R(403,{ok:false,error:'yazma'});
      g.repo=repo;g.branch=branch;
      const m=await PW.make(String(body.pw||''));
      const cur=await this.ghFile('auth.json',t,false);
      if(cur===undefined)return R(0,null);
      const sv=(g.auth&&g.auth.sv|0)||0;
      const rec={v:1,iter:m.iter,salt:m.salt,verify:m.verify,tokenEnc:await PW.enc(m.key,t),sv,repo,branch};
      const p=await this.ghPut('auth.json',rec,cur&&cur.sha,t,'Panel bağlantısı kuruldu');
      if(p.status!==200&&p.status!==201)return R(p.status||0,{ok:false,error:'yazilamadi'});
      g.auth=rec;
      return R(200,{ok:true,token:t});
    }
    if(a==='password'){
      if(!tok||!g.repo)return R(401,{ok:false});
      const pw=String(body.pw||'');if(pw.length<6)return R(400,{ok:false});
      const cur=await this.ghFile('auth.json',tok,true);
      if(cur===undefined)return R(0,null);
      const old=(cur&&cur.json)||g.auth||{};
      const m=await PW.make(pw);
      const sv=(old.sv|0)+1;
      const rec={v:1,iter:m.iter,salt:m.salt,verify:m.verify,tokenEnc:await PW.enc(m.key,tok),sv,repo:g.repo,branch:g.branch};
      const p=await this.ghPut('auth.json',rec,cur&&cur.sha,tok,'Panel şifresi değiştirildi');
      if(p.status===401||p.status===403)return R(401,{ok:false});
      if(p.status!==200&&p.status!==201)return R(p.status||0,{ok:false});
      g.auth=rec;try{localStorage.setItem('ob-sv',String(sv));}catch(e){}
      return R(200,{ok:true});
    }
    if(a==='save'){
      if(!tok||!g.repo)return R(401,{ok:false});
      if(!g.sha&&!body.force){const ex=await this.ghFile('state.json',tok,false);if(ex===undefined)return R(0,null);if(ex)return R(409,{ok:false,error:'conflict'});}
      if(body.force){const ex=await this.ghFile('state.json',tok,false);if(ex===undefined)return R(0,null);g.sha=ex?ex.sha:'';}
      const rev=(body.rev|0)+1;
      const p=await this.ghPut('state.json',{rev,state:body.state},g.sha,tok,'Panel güncellemesi');
      if(p.status===200||p.status===201){g.sha=(p.j&&p.j.content&&p.j.content.sha)||'';return R(200,{ok:true,rev});}
      if(p.status===409||p.status===422)return R(409,{ok:false,error:'conflict'});
      if(p.status===401||p.status===403)return R(401,{ok:false});
      return R(p.status||0,{ok:false});
    }
    if(a==='logout')return R(200,{ok:true});
    return R(404,{ok:false});
  },
  async call(a,body,tok){
    if(this.mode==='gh')return this.ghCall(a,body,tok);
    const h={};if(body!==undefined)h['Content-Type']='application/json';if(tok)h['X-Admin-Token']=tok;
    const ctrl=new AbortController(),to=setTimeout(()=>ctrl.abort(),body!==undefined?60000:6000);
    try{
      const r=await fetch(this.base+'?a='+a+'&_='+Date.now(),{method:body!==undefined?'POST':'GET',headers:h,body:body!==undefined?JSON.stringify(body):undefined,cache:'no-store',signal:ctrl.signal});
      let j=null;try{j=await r.json();}catch(e){}
      return {status:r.status,j};
    }catch(e){return {status:0,j:null};}finally{clearTimeout(to);}
  },
  async probe(){
    const onPages=/\.github\.io$/i.test(location.hostname);
    const cands=window.OB_API?[String(window.OB_API).replace(/\/$/,'')]:(onPages?[]:['/api','api.php']);
    for(const b of cands){
      this.mode='';this.base=b;
      let r=await this.call('state');
      if(r.status===0)r=await this.call('state');
      if(r.status===200&&r.j&&r.j.ok===true&&'rev' in r.j){this.on=true;this.rev=r.j.rev|0;return r.j.state||null;}
    }
    /* GitHub modu: depodaki data/auth.json varsa ortak kayıt depoya yazılır */
    this.mode='gh';
    const au=await this.ghStatic('auth.json');
    this.why=au.status===0?'data/auth.json okunamadı (ağ hatası veya engellendi)':au.status===404?'data/auth.json bulunamadı (404). Depoda "data" klasörünün içinde auth.json olmalı.':au.status!==200?'data/auth.json açılamadı (hata '+au.status+')':(!au.j?'data/auth.json geçerli bir JSON değil.':(au.j.v===1&&au.j.salt?'':'data/auth.json içeriği beklenen biçimde değil.'));
    if(au.status===200&&au.j&&au.j.v===1&&au.j.salt){
      this.gh.auth=au.j;
      if(au.j.repo){this.gh.repo=au.j.repo;this.gh.branch=au.j.branch||'main';}
      else{const g=this.guessRepo();if(g){this.gh.repo=g.repo;this.gh.branch=g.branch;}}
      const r=await this.call('state');
      if(r.status===200&&r.j&&r.j.ok){this.on=true;this.rev=r.j.rev|0;this.why='';return r.j.state||null;}
      this.why='Kayıt dosyası okunamadı (hata '+(r.status||'bağlantı yok')+').';
    }
    this.mode='';
    return undefined; /* sunucu yok (GitHub Pages, düz hosting, dosyadan açma) */
  },
  guessRepo(){
    const m=location.hostname.match(/^([^.]+)\.github\.io$/i);if(!m)return null;
    const seg=location.pathname.split('/').filter(Boolean)[0];
    return {repo:m[1]+'/'+((seg&&!/\.html?$/i.test(seg))?seg:m[1]+'.github.io'),branch:'main'};
  },
  getToken(){try{return localStorage.getItem('ob-admin-token')||'';}catch(e){return '';}},
  setToken(t){this.token=t||'';try{if(t)localStorage.setItem('ob-admin-token',t);else localStorage.removeItem('ob-admin-token');}catch(e){}},
  async check(){
    const t=this.getToken();if(!t||!this.on)return false;
    const r=await this.call('check',undefined,t);
    if(r.status===200&&r.j&&r.j.ok){this.token=t;this.defaultPw=!!r.j.defaultPw;return true;}
    if(r.status===401)this.setToken('');
    return false;
  },
  stripped(s){const o=Object.assign({},s);delete o.auth;return o;}
};

