/* hazır örnek taslakların İngilizce sürümü; kendi yüklediğiniz taslaklar olduğu gibi kalır */
function tplHtml(t){
  const L=lg();
  if(L!=='tr'){
    if(t[L+'Html'])return t[L+'Html'];
    if(L==='en'&&t.htmlEn)return t.htmlEn;
    const k=t.sample&&SAMPLE_KEY[t.title];
    if(k&&SAMPLES_L[L])return tplMemo[L+k]||(tplMemo[L+k]=sampleHTML(Object.assign({},SAMPLES[k],SAMPLES_L[L][k]),L));
  }
  return t.html;
}

