/* ---------- durum ---------- */
let state=defaults();
const S={cat:'all'};
const A={authed:false,tab:'ozet',edit:null,tpl:null,tplFile:null,exportText:''};
const logoSrc=()=>state.brand.logo||LOGO_MARK;
const catName=id=>{const c=state.categories.find(x=>x.id===id);return c?LF(c,'name'):'';};

function commit(msg){
  Store.save(state);
  renderSite();
  if(!$('#admin').hidden)renderAdmin();
  if(Server.on)pushState(msg);else if(msg)toast(msg,true);
}
/* sunucuya yaz: art arda değişiklikler sıraya girer, son hâl gönderilir */
async function pushState(msg,force){
  if(Server.saving){Server.pending=true;Server.pendingMsg=msg||Server.pendingMsg;return;}
  Server.saving=true;
  try{
    const r=await Server.call('save',{state:Server.stripped(state),rev:Server.rev,force:!!force},Server.token);
    if(r.status===200&&r.j&&r.j.ok){Server.rev=r.j.rev;if(msg)toast(Server.mode==='gh'?msg+' Ziyaretçilerde yaklaşık 1 dk içinde görünür.':msg,true);}
    else if(r.status===401){Server.setToken('');A.authed=false;renderAdmin();toast('Oturum bitti veya şifre başka yerden değişti. Tekrar giriş yapın. Son değişiklik kaydedilmedi.');}
    else if(r.status===409){
      const g=await Server.probe();
      if(g){state=hydrate(g);Store.save(state);renderSite();if(!$('#admin').hidden)renderAdmin();}
      toast('Başka bir cihazda değişiklik yapılmış. Güncel hâli yüklendi, lütfen değişikliğinizi tekrar yapın.');
    }
    else toast('Sunucuya kaydedilemedi ('+(r.status||'bağlantı yok')+'). Değişiklik sadece bu cihazda. Bağlantıyı kontrol edip tekrar deneyin.');
  }finally{
    Server.saving=false;
    if(Server.pending){Server.pending=false;const m=Server.pendingMsg;Server.pendingMsg='';pushState(m);}
  }
}

/* ---------- taslaklara marka bilgisini işleme ---------- */
function fill(html){
  const b=state.brand,c=state.contact;
  const map={SITE_ADI:esc(b.name),SLOGAN:esc(b.slogan),LOGO:logoSrc(),TELEFON:esc(phoneDisp(c.phone)),TELEFON_LINK:phoneTel(c.phone),EMAIL:esc(c.email),ADRES:esc(c.address),SAAT:esc(c.hours),INSTAGRAM:igUrl(c.instagram)||'#',WHATSAPP:waLink('')};
  return String(html).replace(/\{\{\s*([A-Z_]+)\s*\}\}/g,(m,k)=>(k in map)?map[k]:m);
}
function frameFix(){
  document.addEventListener('click',function(e){
    var a=e.target.closest&&e.target.closest('a[href]');if(!a)return;
    var h=a.getAttribute('href')||'';
    if(h.charAt(0)==='#'){e.preventDefault();var t=h.length>1?document.getElementById(h.slice(1)):null;if(t)t.scrollIntoView({behavior:'smooth'});else if(h.length<=1)window.scrollTo({top:0,behavior:'smooth'});return;}
    if(!/^(https?:|tel:|mailto:|sms:)/i.test(h))e.preventDefault();
  },true);
}
const FRAME_SCRIPT='<scr'+'ipt>('+frameFix.toString()+')()</scr'+'ipt>';
function withFrameFix(html){const i=html.lastIndexOf('</body>');return i<0?html+FRAME_SCRIPT:html.slice(0,i)+FRAME_SCRIPT+html.slice(i);}

