/* ---------- demo yükleme ekranı: logomuz ortada, etrafında dönen halka ---------- */
function ldrHtml(){
  document.documentElement.style.setProperty('--ldr-logo','url("'+logoSrc()+'")');
  return '<div class="ldr" data-t="'+Date.now()+'" aria-hidden="true"><b class="ldr-ring"></b><i class="ldr-logo"></i></div>';
}
function ldrHide(f){
  const p=f.parentNode,l=p&&p.querySelector(':scope > .ldr');
  if(!l||l.dataset.off)return;l.dataset.off='1';
  const wait=Math.max(900,1600-(Date.now()-(+l.dataset.t||0)));
  setTimeout(()=>{l.classList.add('off');setTimeout(()=>{if(l.parentNode)l.remove();},600);},wait);
}
document.addEventListener('load',e=>{const f=e.target;if(f&&f.tagName==='IFRAME'&&f.hasAttribute('data-demo'))ldrHide(f);},true);

function tplCard(t){
  const cat=catName(t.categoryId);
  return `<article class="tcard"><div class="tthumb">${t.sample?`<span class="badge tbadge">${tt('sample')}</span>`:''}${t.demoUrl?`${ldrHtml()}<iframe data-demo="1" src="${esc(t.demoUrl)}" sandbox="allow-scripts allow-same-origin allow-forms" tabindex="-1" aria-hidden="true" title=""></iframe>`:t.image?`<img class="cover" src="${t.image}" alt="">`:`<iframe data-thumb="${t.id}" sandbox="allow-same-origin" tabindex="-1" aria-hidden="true" title=""></iframe>`}</div><div class="tmeta"><div class="tt"><button type="button" class="tlink" data-tpl="${t.id}">${esc(LF(t,'title'))}</button><small>${esc(cat||tt('template'))}</small></div><span class="tgo">${icon('arrow',16)}</span></div></article>`;
}
function thumbHtml(t){
  return t.demoUrl?`${ldrHtml()}<iframe data-demo="1" src="${esc(t.demoUrl)}" sandbox="allow-scripts allow-same-origin allow-forms" tabindex="-1" aria-hidden="true" title=""></iframe>`:t.image?`<img class="cover" src="${t.image}" alt="">`:`<iframe data-thumb="${t.id}" sandbox="allow-same-origin" tabindex="-1" aria-hidden="true" title=""></iframe>`;
}
function catCard(id,label,items){
  const first=items[0];
  return `<article class="tcard catcard"><div class="tthumb">${first?thumbHtml(first):''}<span class="badge tbadge">${items.length} ${esc(tt('tplN'))}</span></div><div class="tmeta"><div class="tt"><button type="button" class="tlink" data-cat="${esc(id)}">${esc(label)}</button><small>${items.length} ${esc(tt('tplN'))}</small></div><span class="tgo">${icon('arrow',16)}</span></div></article>`;
}
function tplInner(){
  const vis=state.templates.filter(t=>t.visible!==false);
  const known=id=>state.categories.some(c=>c.id===id);
  const cats=state.categories.filter(c=>vis.some(t=>t.categoryId===c.id));
  const otherList=vis.filter(t=>!known(t.categoryId));
  if(S.cat!=='all'&&S.cat!=='other'&&!cats.some(c=>c.id===S.cat))S.cat='all';
  if(S.cat==='other'&&!otherList.length)S.cat='all';
  if(S.cat==='all'){
    const cards=cats.map(c=>catCard(c.id,LF(c,'name'),vis.filter(t=>t.categoryId===c.id))).join('')+(otherList.length?catCard('other',tt('other'),otherList):'');
    return cards?`<div class="grid g3 catgrid">${cards}</div>`:`<div class="empty">${tt('noTpl')}</div>`;
  }
  const list=S.cat==='other'?otherList:vis.filter(t=>t.categoryId===S.cat);
  const cn=S.cat==='other'?tt('other'):LF(state.categories.find(c=>c.id===S.cat)||{},'name');
  const back=`<div class="tbar"><button type="button" class="tback" data-cat="all">${icon('arrow',16)}<span>${esc(tt('backCats'))}</span></button><h3>${esc(cn)} <small>${list.length}</small></h3></div>`;
  return back+(list.length?`<div class="grid g3">${list.map(tplCard).join('')}</div>`:`<div class="empty">${tt('noTpl')}</div>`);
}
function refreshTpl(){const w=$('#tpl-wrap');if(!w)return;w.innerHTML=tplInner();mountFrames();fitThumbs();}

