function mountFrames(){
  $$('iframe[data-thumb]').forEach(f=>{const t=state.templates.find(x=>x.id===f.dataset.thumb);if(t)f.srcdoc=fill(tplHtml(t));});
}
function fitThumbs(){
  $$('.tthumb').forEach(el=>{const f=$('iframe',el);if(f&&el.clientWidth)f.style.transform='scale('+(el.clientWidth/1280)+')';});
}
function updateQuote(){
  if(!$('#q-form'))return;
  const n=$('#q-name').value.trim(),p=$('#q-phone').value.trim(),tp=$('#q-topic').value,m=$('#q-msg').value.trim();
  const l=[wam(`Merhaba ${state.brand.name}, bilgi almak istiyorum.`,`Hello ${state.brand.name}, I would like some information.`,`Guten Tag ${state.brand.name}, ich hätte gern einige Informationen.`,`مرحباً ${state.brand.name}، أود الحصول على بعض المعلومات.`)];
  if(n)l.push(wam('Adım: ','Name: ','Name: ','الاسم: ')+n);if(tp)l.push(wam('Konu: ','Topic: ','Anliegen: ','الموضوع: ')+tp);if(p)l.push(wam('Telefon: ','Phone: ','Telefon: ','الهاتف: ')+p);if(m)l.push(wam('Mesaj: ','Message: ','Nachricht: ','الرسالة: ')+m);
  $('#q-send').href=waLink(l.join('\n'));
}
function updateGoogle(){
  const q=$('#g-q');if(!q)return;
  const v=q.value.trim();
  $('#g-search').href=v?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(v):'https://www.google.com/maps';
  $('#g-add').href=waLink(wam(`Merhaba ${state.brand.name}, işletmem Google Haritalar'da görünmüyor. İşletme profili oluşturmak istiyorum.`+(v?`\nİşletme: ${v}`:''),`Hello ${state.brand.name}, my business does not show up on Google Maps. I would like to set up a business profile.`+(v?`\nBusiness: ${v}`:''),`Guten Tag ${state.brand.name}, mein Unternehmen ist auf Google Maps nicht zu finden. Ich möchte ein Unternehmensprofil einrichten.`+(v?`\nUnternehmen: ${v}`:''),`مرحباً ${state.brand.name}، نشاطي لا يظهر على خرائط جوجل وأود إنشاء ملف تجاري.`+(v?`\nالنشاط: ${v}`:'')));
}

/* ---------- bildirim ---------- */
let toastT=null;
function toast(msg,withLink){
  const t=$('#toast');
  t.innerHTML=`<span>${esc(msg)}</span>${withLink&&!$('#admin').hidden?`<a href="#site">Siteyi gör</a>`:''}`;
  t.hidden=false;clearTimeout(toastT);toastT=setTimeout(()=>{t.hidden=true;},4200);
}

/* ---------- önizleme penceresi ---------- */
let lastFocus=null;
function openViewer(o){
  const v=$('#viewer');lastFocus=document.activeElement;
  v.innerHTML=`<div class="vbar"><div class="vtitle"><b>${esc(o.title)}</b><span>${esc(o.sub||'')}</span></div>
  <div class="seg" role="group" aria-label="${tt('devGroup')}">${[['phone',tt('devPhone')],['tablet',tt('devTablet')],['desktop',tt('devDesktop')]].map(([d,l])=>`<button type="button" data-dev="${d}" aria-pressed="${d==='desktop'}" aria-label="${l}">${icon(d,16)}<span>${l}</span></button>`).join('')}</div>
  ${o.action?`<a class="btn btn-primary btn-sm" href="${esc(o.action.href)}" target="_blank" rel="noopener">${esc(o.action.label)}</a>`:''}
  <button type="button" class="iconbtn" data-vclose aria-label="${tt('close')}">${icon('x',20)}</button></div>
  <div class="vstage"><div class="vframe" data-d="desktop"><iframe title="${esc(o.title)}"></iframe></div></div>`;
  const f=$('iframe',v);
  if(o.ldr){f.setAttribute('data-demo','1');f.parentNode.insertAdjacentHTML('beforeend',ldrHtml());}
  if(o.html!=null){f.setAttribute('sandbox','allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox');f.srcdoc=o.html;}
  else{f.setAttribute('sandbox','allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox');f.src=o.url;}
  v.hidden=false;$('#pv').hidden=true;$('#waFloat').hidden=true;
  document.documentElement.style.overflow='hidden';
  $('[data-vclose]',v).focus();
}
function closeViewer(){
  const v=$('#viewer');if(v.hidden)return;
  v.hidden=true;v.innerHTML='';$('#pv').hidden=$('#site').hidden;$('#waFloat').hidden=$('#site').hidden;
  document.documentElement.style.overflow='';
  if(lastFocus&&lastFocus.focus)try{lastFocus.focus();}catch(e){}
}
function openTpl(id){
  const t=state.templates.find(x=>x.id===id);if(!t)return;
  const tn=LF(t,'title');openViewer({title:tn,sub:(catName(t.categoryId)||tt('template'))+' · '+tt('tplSub'),...(t.demoUrl?{url:t.demoUrl,ldr:true}:{html:withFrameFix(fill(tplHtml(t)))}),action:{label:tt('wantTpl'),href:waLink(wam(`Merhaba ${state.brand.name}, "${tn}" taslağını istiyorum.`,`Hello ${state.brand.name}, I would like the "${tn}" template.`,`Guten Tag ${state.brand.name}, ich möchte die Vorlage „${tn}“.`,`مرحباً ${state.brand.name}، أريد القالب «${tn}».`))}});
}
function openWork(id){
  const w=state.works.find(x=>x.id===id);if(!w||!w.url)return;
  openViewer({title:LF(w,'title'),sub:tt('workSub'),url:w.url,action:{label:tt('newTab'),href:w.url}});
}

/* ---------- site olayları ---------- */
function bindSite(){
  const site=$('#site');
  site.addEventListener('click',e=>{
    const lg=e.target.closest('[data-lang]');if(lg){setLang(lg.dataset.lang);return;}
    const sc=e.target.closest('[data-scroll]');
    if(sc){e.preventDefault();const id=sc.dataset.scroll;if(id==='top')window.scrollTo({top:0,behavior:'smooth'});else{const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'});}$('#nav').classList.remove('open');$('#menuBtn').setAttribute('aria-expanded','false');return;}
    if(e.target.closest('#menuBtn')){const n=$('#nav');const o=n.classList.toggle('open');$('#menuBtn').setAttribute('aria-expanded',String(o));return;}
    const ch=e.target.closest('[data-cat]');if(ch){S.cat=ch.dataset.cat;refreshTpl();const sec=document.getElementById('taslaklar');if(sec)sec.scrollIntoView({block:'start'});return;}
    const tp=e.target.closest('[data-tpl]');if(tp){openTpl(tp.dataset.tpl);return;}
    const wk=e.target.closest('[data-work]');if(wk){openWork(wk.dataset.work);return;}
    const cp=e.target.closest('[data-copy]');if(cp){copyText(cp.dataset.copy);return;}
    if(e.target.closest('#q-send')&&!$('#q-name').value.trim()){e.preventDefault();$('#q-err').textContent=tt('fNeedName');$('#q-name').focus();}
  });
  site.addEventListener('input',e=>{
    if(e.target.closest('#q-form')){updateQuote();if(e.target.id==='q-name')$('#q-err').textContent='';}
    if(e.target.id==='g-q')updateGoogle();
  });
  site.addEventListener('change',e=>{if(e.target.id==='q-topic')updateQuote();});
  $('#viewer').addEventListener('click',e=>{
    if(e.target.closest('[data-vclose]')){closeViewer();return;}
    const d=e.target.closest('[data-dev]');
    if(d){$('.vframe',$('#viewer')).dataset.d=d.dataset.dev;$$('[data-dev]',$('#viewer')).forEach(b=>b.setAttribute('aria-pressed',String(b===d)));}
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeViewer();});
  window.addEventListener('resize',fitThumbs);
}
async function copyText(txt){
  try{await navigator.clipboard.writeText(txt);toast(tt('copied'));}
  catch(e){const ta=$('#exp-text');if(ta&&ta.value===txt)ta.select();toast(tt('copyFail'));}
}

/* ============================================================
   TASLAK İŞLEME  (ZIP / HTML  ->  tek sayfa, marka alanları bulunur)
   ============================================================ */
const MIME={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',svg:'image/svg+xml',webp:'image/webp',avif:'image/avif',ico:'image/x-icon',woff:'font/woff',woff2:'font/woff2',ttf:'font/ttf',otf:'font/otf',mp4:'video/mp4',webm:'video/webm',mp3:'audio/mpeg'};
const extOf=p=>(String(p).split('?')[0].split('#')[0].split('.').pop()||'').toLowerCase();
const isLocal=u=>!!u&&!/^([a-z][a-z0-9+.-]*:|\/\/|#)/i.test(String(u).trim());
function resolvePath(base,rel){
  rel=String(rel).split('#')[0].split('?')[0];
  try{rel=decodeURIComponent(rel);}catch(e){}
  const parts=rel.startsWith('/')?[]:base.split('/').filter(Boolean);
  rel.split('/').forEach(s=>{if(s==='..')parts.pop();else if(s&&s!=='.')parts.push(s);});
  return parts.join('/');
}
function parseHtml(code){return new DOMParser().parseFromString(code,'text/html');}

async function zipToDoc(file){
  if(!window.JSZip)throw new Error('ZIP okuyucu yüklenemedi. HTML dosyasını yükleyin ya da kodu yapıştırın.');
  if(file.size>25*1024*1024)throw new Error('ZIP dosyası 25 MB sınırını aşıyor.');
  const zip=await JSZip.loadAsync(file);
  const names=Object.keys(zip.files).filter(n=>!zip.files[n].dir&&!/(^|\/)(__MACOSX|node_modules|\.git)\//.test(n));
  const lower={};names.forEach(n=>{lower[n.toLowerCase()]=n;});
  const rank=a=>(/(^|\/)index\.html?$/i.test(a)?0:1);
  const htmls=names.filter(n=>/\.html?$/i.test(n)).sort((a,b)=>rank(a)-rank(b)||a.split('/').length-b.split('/').length||a.length-b.length);
  if(!htmls.length)throw new Error('ZIP içinde HTML dosyası bulunamadı.');
  const entry=htmls[0];
  const dirOf=n=>n.includes('/')?n.slice(0,n.lastIndexOf('/')+1):'';
  const base=dirOf(entry);
  const find=(rel,b)=>lower[resolvePath(b,rel).toLowerCase()];
  const text=n=>zip.file(n).async('string');
  const dataURI=async n=>'data:'+(MIME[extOf(n)]||'application/octet-stream')+';base64,'+await zip.file(n).async('base64');
  const inlineCss=async(css,b)=>{
    const re=/url\(\s*(['"]?)([^'")]+?)\1\s*\)/g;const urls=new Set();
    css.replace(re,(m,q,u)=>{urls.add(u);return m;});
    const map={};
    for(const u of urls){if(!isLocal(u))continue;const n=find(u,b);if(n)map[u]=await dataURI(n);}
    return css.replace(re,(m,q,u)=>map[u]?'url("'+map[u]+'")':m);
  };
  const doc=parseHtml(await text(entry));
  for(const st of $$('style',doc))st.textContent=await inlineCss(st.textContent,base);
  for(const l of $$('link[rel~="stylesheet"][href]',doc)){
    const h=l.getAttribute('href');if(!isLocal(h))continue;const n=find(h,base);if(!n)continue;
    const st=doc.createElement('style');st.textContent=await inlineCss(await text(n),dirOf(n));l.replaceWith(st);
  }
  for(const el of $$('[style*="url("]',doc))el.setAttribute('style',await inlineCss(el.getAttribute('style'),base));
  for(const s of $$('script[src]',doc)){
    const h=s.getAttribute('src');if(!isLocal(h))continue;const n=find(h,base);if(!n)continue;
    const ns=doc.createElement('script');if(s.getAttribute('type'))ns.setAttribute('type',s.getAttribute('type'));
    ns.textContent=(await text(n)).replace(/<\/script/gi,'<\\/script');
    if(s.hasAttribute('defer')||s.getAttribute('type')==='module'){s.remove();doc.body.appendChild(ns);}else s.replaceWith(ns);
  }
  for(const el of $$('img[src],source[src],audio[src],video[src],video[poster],input[type=image][src],link[rel~="icon"][href]',doc)){
    for(const a of ['src','poster','href']){const v=el.getAttribute(a);if(v&&isLocal(v)){const n=find(v,base);if(n)el.setAttribute(a,await dataURI(n));}}
  }
  for(const el of $$('[srcset]',doc)){
    const out=[];
    for(const p of el.getAttribute('srcset').split(',').map(s=>s.trim()).filter(Boolean)){
      const bits=p.split(/\s+/);const n=isLocal(bits[0])?find(bits[0],base):null;
      out.push(n?[await dataURI(n)].concat(bits.slice(1)).join(' '):p);
    }
    el.setAttribute('srcset',out.join(', '));
  }
  return doc;
}

function textNodes(doc){
  const w=doc.createTreeWalker(doc.body,NodeFilter.SHOW_TEXT);const a=[];let n;
  while((n=w.nextNode())){const p=n.parentNode&&n.parentNode.nodeName;if(p==='SCRIPT'||p==='STYLE'||p==='NOSCRIPT')continue;a.push(n);}
  return a;
}
function analyze(doc){
  const cand=new Map();
  const add=(t,w)=>{t=String(t||'').replace(/\s+/g,' ').trim();if(t.length<2||t.length>40)return;cand.set(t,(cand.get(t)||0)+w);};
  $$('[class*="logo" i],[class*="brand" i],[id*="logo" i],[id*="brand" i],.navbar-brand,.site-title',doc).forEach(el=>{if(!el.querySelector('div,section,ul,nav,header'))add(el.textContent,3);});
  add((doc.title||'').split(/\s[|\-–—:·]\s/)[0],2);
  $$('img[alt]',doc).forEach(i=>{const al=i.getAttribute('alt');if(/logo/i.test(al))add(al.replace(/\blogo\b/ig,''),1);});
  const names=Array.from(cand.entries()).sort((a,b)=>b[1]-a[1]).slice(0,4).map(e=>e[0]);

  const logos=[];
  $$('img,svg',doc).forEach((el,idx)=>{
    if(logos.length>=3)return;
    const tag=el.tagName.toLowerCase();
    const src=tag==='img'?(el.getAttribute('src')||''):'';
    const attrs=(el.getAttribute('class')||'')+' '+(el.id||'')+' '+(el.getAttribute('alt')||'')+' '+(/^data:/i.test(src)?'':src);
    const inLogo=el.closest('[class*="logo" i],[class*="brand" i],[id*="logo" i],[id*="brand" i]');
    if(/logo/i.test(attrs)||inLogo)logos.push({idx,tag,src});
  });
  if(!logos.length){
    $$('img,svg',doc).some((el,idx)=>{if(el.closest('header,nav')){logos.push({idx,tag:el.tagName.toLowerCase(),src:el.tagName.toLowerCase()==='img'?(el.getAttribute('src')||''):''});return true;}return false;});
  }

  const phones=[],emails=[],sp=new Set(),se=new Set();
  textNodes(doc).forEach(n=>{
    (n.nodeValue.match(/\+?\d[\d\s().-]{8,16}\d/g)||[]).forEach(m=>{m=m.trim();const d=digits(m);if(d.length>=10&&d.length<=13&&!sp.has(m)){sp.add(m);phones.push(m);}});
    (n.nodeValue.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g)||[]).forEach(m=>{if(!se.has(m)){se.add(m);emails.push(m);}});
  });
  return {names,logos,phones,emails,
    tel:$$('a[href^="tel:" i]',doc).length,
    mail:$$('a[href^="mailto:" i]',doc).length,
    ig:$$('a[href*="instagram.com"]',doc).length,
    wa:$$('a[href*="wa.me"],a[href*="api.whatsapp.com"]',doc).length};
}
function buildSel(doc){
  const f=analyze(doc);
  return {
    names:f.names.map((t,i)=>({text:t,on:i===0})),
    logos:f.logos.map(l=>({...l,on:true})),
    phones:f.phones.map(t=>({text:t,on:true})),
    emails:f.emails.map(t=>({text:t,on:true})),
    tel:{n:f.tel,on:f.tel>0},mail:{n:f.mail,on:f.mail>0},ig:{n:f.ig,on:f.ig>0},wa:{n:f.wa,on:f.wa>0}
  };
}
function countOcc(doc,s){
  if(!s)return 0;let n=0;
  textNodes(doc).forEach(t=>{n+=t.nodeValue.split(s).length-1;});
  $$('[alt],[title],meta[content]',doc).forEach(el=>['alt','title','content'].forEach(a=>{const v=el.getAttribute(a);if(v)n+=v.split(s).length-1;}));
  return n+((doc.title||'').split(s).length-1);
}
function applyBranding(doc,sel){
  const els=$$('img,svg',doc);
  sel.logos.filter(l=>l.on).forEach(l=>{
    const el=els[l.idx];if(!el)return;
    if(el.tagName.toLowerCase()==='svg'){const im=doc.createElement('img');im.setAttribute('src','{{LOGO}}');im.setAttribute('alt','{{SITE_ADI}}');im.setAttribute('style','height:40px;width:auto');el.replaceWith(im);}
    else{el.setAttribute('src','{{LOGO}}');el.removeAttribute('srcset');}
  });
  $$('a[href]',doc).forEach(a=>{
    const h=a.getAttribute('href')||'';
    if(sel.tel.on&&/^tel:/i.test(h))a.setAttribute('href','tel:{{TELEFON_LINK}}');
    else if(sel.mail.on&&/^mailto:/i.test(h))a.setAttribute('href','mailto:{{EMAIL}}');
    else if(sel.ig.on&&/instagram\.com/i.test(h))a.setAttribute('href','{{INSTAGRAM}}');
    else if(sel.wa.on&&/(wa\.me|api\.whatsapp\.com)/i.test(h))a.setAttribute('href','{{WHATSAPP}}');
  });
  const reps=[].concat(
    sel.names.filter(x=>x.on&&x.text.trim()).map(x=>[x.text.trim(),'{{SITE_ADI}}']),
    sel.phones.filter(x=>x.on&&x.text.trim()).map(x=>[x.text.trim(),'{{TELEFON}}']),
    sel.emails.filter(x=>x.on&&x.text.trim()).map(x=>[x.text.trim(),'{{EMAIL}}'])
  ).sort((a,b)=>b[0].length-a[0].length);
  const rep=s=>{let r=s;for(const p of reps)r=r.split(p[0]).join(p[1]);return r;};
  textNodes(doc).forEach(n=>{const v=rep(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v;});
  $$('[alt],[title],meta[content]',doc).forEach(el=>['alt','title','content'].forEach(a=>{const v=el.getAttribute(a);if(v){const r=rep(v);if(r!==v)el.setAttribute(a,r);}}));
  if(doc.title){const r=rep(doc.title);if(r!==doc.title)doc.title=r;}
  return doc;
}
function buildFinal(){
  const T=A.tpl;const clone=T.doc.cloneNode(true);applyBranding(clone,T.sel);
  return '<!DOCTYPE html>\n'+clone.documentElement.outerHTML;
}

/* ---------- görsel okuma (küçültür) ---------- */
function readImage(file,max=900,q=.84){
  return new Promise((res,rej)=>{
    const fr=new FileReader();fr.onerror=()=>rej(new Error('okunamadı'));
    fr.onload=()=>{
      if(file.type==='image/svg+xml'){res(fr.result);return;}
      const im=new Image();
      im.onload=()=>{
        const k=Math.min(1,max/Math.max(im.width,im.height));
        const c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*k));c.height=Math.max(1,Math.round(im.height*k));
        c.getContext('2d').drawImage(im,0,0,c.width,c.height);
        res(c.toDataURL(/png|webp|gif/.test(file.type)?'image/png':'image/jpeg',q));
      };
      im.onerror=()=>rej(new Error('görsel'));im.src=fr.result;
    };
    fr.readAsDataURL(file);
  });
}

