function fld(o){
  const id='f-'+o.id;const v=o.value==null?'':o.value;const span=o.span?' span2':'';
  if(o.type==='check')return `<label class="check${span}" for="${id}"><input type="checkbox" id="${id}" name="${o.id}"${v?' checked':''}><span>${esc(o.label)}</span></label>`;
  let ctl='';
  if(o.type==='textarea')ctl=`<textarea id="${id}" name="${o.id}" rows="${o.rows||3}" placeholder="${esc(o.ph||'')}">${esc(v)}</textarea>`;
  else if(o.type==='select')ctl=`<select id="${id}" name="${o.id}">${o.options.map(p=>`<option value="${esc(p[0])}"${String(p[0])===String(v)?' selected':''}>${esc(p[1])}</option>`).join('')}</select>`;
  else if(o.type==='image'){
    const shown=v||o.fallback||'';
    ctl=`<div class="imgfield"><div class="imgprev" id="${id}-prev">${shown?`<img src="${esc(shown)}" alt="">`:'<span>Görsel yok</span>'}</div><div class="imgbtns"><input type="file" id="${id}-file" accept="image/*" data-imgfor="${id}" data-max="${o.max||900}"><button class="btn btn-ghost btn-sm" type="button" data-act="img-clear" data-for="${id}"${o.fallback?' data-fb="logo"':''}>${esc(o.clearLabel||'Kaldır')}</button></div><input type="hidden" id="${id}" name="${o.id}" value="${esc(v)}"></div>`;
  }
  else ctl=`<input type="${o.type||'text'}" id="${id}" name="${o.id}" value="${esc(v)}" placeholder="${esc(o.ph||'')}"${o.type==='password'?' autocomplete="new-password"':''}>`;
  return `<div class="field${span}"><label for="${o.type==='image'?id+'-file':id}">${esc(o.label)}</label>${ctl}${o.help?`<small class="help">${esc(o.help)}</small>`:''}</div>`;
}
