/* ---------- otomatik çeviri: yeni kategori/kayıt kaydedilince İngilizce, Almanca ve Arapçaya çevrilir ---------- */
const MT_CACHE={};
function decEnt(t){const e=document.createElement('textarea');e.innerHTML=t;return e.value;}
async function mtTranslate(text,lc){
  const key=lc+'|'+text;if(MT_CACHE[key])return MT_CACHE[key];
  const ctrl=new AbortController(),to=setTimeout(()=>ctrl.abort(),9000);
  try{
    const r=await fetch('https://api.mymemory.translated.net/get?q='+encodeURIComponent(text)+'&langpair=tr|'+lc,{signal:ctrl.signal});
    const j=await r.json();
    let t=j&&j.responseData&&j.responseData.translatedText;
    if(!t||String(j.responseStatus)!=='200'||/MYMEMORY|INVALID|QUERY LENGTH/i.test(t))return '';
    t=decEnt(String(t)).trim();
    if(t)MT_CACHE[key]=t;
    return t;
  }catch(e){return '';}finally{clearTimeout(to);}
}
async function autoTranslate(k,it){
  const fields=(ENF[k]||[]).filter(f=>!['price','features'].includes(f[0]));
  it._at=it._at||{};
  const jobs=[];
  ['en','de','ar'].forEach(lc=>{
    it[lc]=it[lc]||{};it._at[lc]=it._at[lc]||{};
    fields.forEach(([id])=>{
      const src=String(it[id]==null?'':it[id]).trim();if(!src)return;
      const cur=String(it[lc][id]||'').trim(),rec=it._at[lc][id];
      const stale=rec&&rec.out===cur&&rec.src!==src;
      if(cur&&!stale)return;
      const known=AUTO[lc]&&AUTO[lc][src];
      if(known){it[lc][id]=known;it._at[lc][id]={src,out:known};jobs.push(Promise.resolve(true));return;}
      jobs.push(mtTranslate(src,lc).then(t=>{if(t){it[lc][id]=t;it._at[lc][id]={src,out:t};return true;}return false;}));
    });
  });
  const res=await Promise.all(jobs);
  return {changed:res.some(Boolean),failed:res.some(x=>!x)};
}
function saveColl(form){
  const k=form.dataset.coll,C=COLLS[k];
  const d=readForm(form);
  const tr={en:{},de:{},ar:{}};Object.keys(d).forEach(x=>{const m=/^(en|de|ar)_(.+)$/.exec(x);if(m){const key=m[2],v=String(d[x]).trim();if(v)tr[m[1]][key]=key==='features'?v.split('\n').map(z=>z.trim()).filter(Boolean):v;delete d[x];}});
  const base=A.edit.id?state[k].find(x=>x.id===A.edit.id):null;
  const p=C.parse(d,base);
  if(p.error){formErr(form,p.error);return;}
  p.en=tr.en;p.de=tr.de;p.ar=tr.ar;
  let item;
  if(base){Object.assign(base,p);delete base.sample;item=base;}
  else{item=Object.assign({id:uid()},C.blank(),p);state[k].push(item);}
  A.edit=null;
  commit(C.noun.charAt(0).toLocaleUpperCase('tr')+C.noun.slice(1)+' kaydedildi. Site güncellendi.');
  if(ENF[k]){
    toast('Diğer dillere çevriliyor…');
    autoTranslate(k,item).then(r=>{
      if(r.changed){Store.save(state);renderSite();if(!$('#admin').hidden)renderAdmin();}
      toast(r.failed?(r.changed?'Bazı çeviriler yapılamadı (internet?). Düzenleyip elle yazabilirsiniz.':'Otomatik çeviri yapılamadı (internet bağlantısı?). Düzenleyip elle yazabilirsiniz.'):'Çeviri tamam: İngilizce, Almanca ve Arapça eklendi.',true);
    });
  }
}

