function tplReview(){
  const T=A.tpl,sel=T.sel;
  const chk=(g,i,k,on)=>`<input type="checkbox" data-sel="${g}" ${i!==undefined?`data-i="${i}" `:''}data-k="${k}"${on?' checked':''} aria-label="Değiştir">`;
  const textRows=(g,arr,none)=>arr.length?arr.map((n,i)=>`<div class="it">${chk(g,i,'on',n.on)}<input type="text" data-sel="${g}" data-i="${i}" data-k="text" value="${esc(n.text)}" aria-label="Bulunan metin"><small>${countOcc(T.doc,n.text)} yerde</small></div>`).join(''):`<p class="help">${none}</p>`;
  const toggle=(g,label)=>sel[g].n?`<div class="it">${chk(g,undefined,'on',sel[g].on)}<span>${label} (${sel[g].n})</span></div>`:'';
  const logos=sel.logos.length?sel.logos.map((l,i)=>`<div class="it">${chk('logos',i,'on',l.on)}${l.src?`<img class="lg" src="${esc(l.src)}" alt="">`:'<span class="badge off">SVG logo</span>'}<small>Sizin logonuzla değişir</small></div>`).join(''):'<p class="help">Logo bulunamadı. Taslak logosuz kalır.</p>';
  const kb=Math.round(buildFinal().length/1024);
  return `<div class="panel"><h3>Bulunan bilgiler: ${esc(T.title)}</h3><p class="help">İşaretli olanlar sizin bilgilerinizle otomatik değişir. Yanlış bulunan varsa işareti kaldırın ya da metni düzeltin. Logo, ad ve telefonu panelden değiştirdiğinizde bu taslak da güncellenir.</p>
  <div class="found" style="gap:18px">
    <div class="found"><span class="lbl">Marka adı</span>${textRows('names',sel.names,'Marka adı bulunamadı. Aşağıdan elle ekleyebilirsiniz.')}<div class="it"><input type="text" id="rv-extra" placeholder="Değişecek başka bir metin yazın" aria-label="Değişecek ek metin"><button type="button" class="btn btn-ghost btn-sm" data-act="tpl-addtext">Ekle</button></div></div>
    <div class="found"><span class="lbl">Logo</span>${logos}</div>
    <div class="found"><span class="lbl">Telefon</span>${textRows('phones',sel.phones,'Metin içinde telefon numarası bulunamadı.')}${toggle('tel','Ara (tel:) bağlantıları')}</div>
    <div class="found"><span class="lbl">E-posta</span>${textRows('emails',sel.emails,'E-posta bulunamadı.')}${toggle('mail','E-posta (mailto:) bağlantıları')}</div>
    <div class="found"><span class="lbl">Sosyal ve mesaj bağlantıları</span>${toggle('ig','Instagram bağlantıları')}${toggle('wa','WhatsApp bağlantıları')}${(!sel.ig.n&&!sel.wa.n)?'<p class="help">Bu tür bağlantı bulunamadı.</p>':''}</div>
  </div></div>
  <div class="panel"><h3>Sonuç önizlemesi</h3><p class="help">Şu anki işaretlere göre taslak (${kb} KB). Ayarları değiştirince önizlemeyi yenileyin.</p><iframe class="rv-frame" id="rv-frame" sandbox="allow-scripts allow-popups" title="Taslak önizlemesi"></iframe>
  ${kb>6000?'<p class="err">Dosya büyük. Sitede yavaş açılabilir, görselleri küçültmeyi düşünün.</p>':''}
  <p class="err" data-err>${esc(T.err)}</p>
  <div class="actions"><button class="btn btn-primary" type="button" data-act="tpl-save">Kaydet ve yayınla</button><button class="btn btn-ghost" type="button" data-act="tpl-refresh">Önizlemeyi yenile</button><button class="btn btn-ghost" type="button" data-act="tpl-back">Geri</button></div></div>`;
}
function tplPreview(){const f=$('#rv-frame');if(f&&A.tpl&&A.tpl.doc)f.srcdoc=withFrameFix(fill(buildFinal()));}
async function tplAnalyze(form){
  const d=readForm(form),T=A.tpl;
  Object.assign(T,{title:d.title,categoryId:d.categoryId,desc:d.desc,sourceUrl:d.sourceUrl,cover:d.cover,mode:d.mode,code:d.code||'',err:''});
  if(!T.title.trim()){T.err='Taslak adı gerekli.';renderAdmin();return;}
  const btn=$('button[type=submit]',form);if(btn){btn.disabled=true;btn.textContent='İnceleniyor...';}
  try{
    let doc;
    if(T.mode==='code'){if(!T.code.trim())throw new Error('HTML kodunu yapıştırın.');doc=parseHtml(T.code);}
    else{
      const f=A.tplFile;if(!f)throw new Error('Bir dosya seçin.');
      doc=T.mode==='zip'?await zipToDoc(f):parseHtml(await f.text());
    }
    T.doc=doc;T.sel=buildSel(doc);T.stage='review';T.err='';
  }catch(err){T.err=(err&&err.message)||'Dosya okunamadı.';}
  renderAdmin();
}
function tplSave(){
  const T=A.tpl;let html;
  try{html=buildFinal();}catch(e){T.err='Taslak oluşturulamadı.';renderAdmin();return;}
  if(html.length>12e6){T.err='Taslak 12 MB sınırını aşıyor. Büyük görselleri küçültüp tekrar deneyin.';renderAdmin();return;}
  state.templates.push({id:uid(),title:T.title.trim(),categoryId:T.categoryId||'',desc:T.desc||'',sourceUrl:T.sourceUrl||'',image:T.cover||'',html,visible:true});
  A.tpl=null;A.tplFile=null;
  commit('Taslak eklendi. Sitede hemen görünür.');
}
function setSel(el){
  const T=A.tpl;if(!T||!T.sel)return;
  const g=el.dataset.sel,k=el.dataset.k;const v=el.type==='checkbox'?el.checked:el.value;
  const tgt=el.dataset.i!==undefined?T.sel[g][+el.dataset.i]:T.sel[g];
  if(tgt)tgt[k]=v;
}

